import{_ as a,m as n,n as e,q as l}from"./chunks/framework.DMDh-7Lg.js";const y=JSON.parse('{"title":"Command Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/commands.md","filePath":"reference/commands.md"}'),o={name:"reference/commands.md"};function p(t,s,r,i,c,F){return n(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h1><p>This page describes the command model as it exists in the current Klix implementation.</p><p>For tutorial-style usage, see <a href="./../guides/adding-commands">Adding Commands</a>. For parser behavior, see <a href="./../concepts/router">Router</a>.</p><h2 id="registration" tabindex="-1">Registration <a class="header-anchor" href="#registration" aria-label="Permalink to &quot;Registration&quot;">​</a></h2><p>Register commands with <code>@app.command(...)</code>:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/status</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Show current status</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> status</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">print</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Healthy.</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> color</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">success</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>Arguments accepted by the decorator:</p><ul><li><code>name</code>: required slash-prefixed command name</li><li><code>help</code>: optional help text</li><li><code>aliases</code>: optional list of alternate names</li><li><code>args_schema</code>: optional Pydantic model for typed arguments</li></ul><h2 id="handler-signatures" tabindex="-1">Handler Signatures <a class="header-anchor" href="#handler-signatures" aria-label="Permalink to &quot;Handler Signatures&quot;">​</a></h2><p>Supported handler shapes are:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> handler</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> handler</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">args</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> SomeSchema</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> def</span><span style="color:#82AAFF;"> handler</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#C792EA;">async</span><span style="color:#C792EA;"> def</span><span style="color:#82AAFF;"> handler</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">args</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> SomeSchema</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><p>If an argument schema is present, Klix passes the parsed schema instance as the first argument.</p><h2 id="aliases" tabindex="-1">Aliases <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Aliases&quot;">​</a></h2><p>Aliases register additional command names that resolve to the same <code>Command</code> object.</p><p>Example:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/deploy</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> aliases</span><span style="color:#89DDFF;">=[</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/ship</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">])</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> deploy</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    ...</span></span></code></pre></div><p>Autocomplete and help generation can include alias names.</p><h2 id="argument-parsing-model" tabindex="-1">Argument Parsing Model <a class="header-anchor" href="#argument-parsing-model" aria-label="Permalink to &quot;Argument Parsing Model&quot;">​</a></h2><p>The command router uses a simple tokenization strategy:</p><ul><li>split input on whitespace</li><li>first token is the command name</li><li>remaining tokens become positionals or flags</li></ul><p>Flags:</p><ul><li><code>--flag value</code></li><li><code>--boolean-flag</code></li></ul><p>Positionals are mapped in the schema field declaration order.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Validation is delegated to Pydantic.</p><p>When validation fails, Klix raises <code>ArgValidationError</code> for field-level issues or surfaces the underlying parse failure through the command execution flow.</p><h2 id="help-generation" tabindex="-1">Help Generation <a class="header-anchor" href="#help-generation" aria-label="Permalink to &quot;Help Generation&quot;">​</a></h2><p><code>app.generate_help()</code> formats registered commands, aliases, and argument placeholders into a readable help listing.</p><p>Typical pattern:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">command</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">/help</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> help</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Show commands</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#C792EA;">def</span><span style="color:#82AAFF;"> help_cmd</span><span style="color:#89DDFF;">(</span><span style="color:#BABED8;font-style:italic;">session</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">Session</span><span style="color:#89DDFF;">)</span><span style="color:#89DDFF;"> -&gt;</span><span style="color:#89DDFF;"> None:</span></span>
<span class="line"><span style="color:#BABED8;">    session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">output</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">panel</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">app</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">generate_help</span><span style="color:#89DDFF;">(),</span><span style="color:#BABED8;font-style:italic;"> title</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Commands</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><h2 id="built-in-behavior" tabindex="-1">Built-In Behavior <a class="header-anchor" href="#built-in-behavior" aria-label="Permalink to &quot;Built-In Behavior&quot;">​</a></h2><p>The main app loop treats these specially:</p><ul><li><code>/exit</code></li><li><code>/quit</code></li></ul><p>Those are handled by the loop itself to terminate the session cleanly.</p><p><code>/help</code> is not built in as behavior. You should register it yourself if you want a help command.</p><h2 id="current-limitations" tabindex="-1">Current Limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current Limitations&quot;">​</a></h2><ul><li>no nested subcommand router</li><li>no shell-quote aware parser</li><li>no schema-driven autocomplete generation</li><li>no built-in command groups beyond naming conventions</li></ul><p>These are design constraints, not bugs. Klix keeps the routing layer intentionally small.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Forgetting the slash prefix.</li><li>Expecting quoted strings with spaces to parse as one argument.</li><li>Using aliases that conflict with another command’s primary name.</li><li>Hiding essential usage details in code instead of <code>help</code> text.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./api">Reference: API</a></li><li><a href="./middleware">Reference: Middleware</a></li><li><a href="./../faq">FAQ</a></li></ul>`,42)])])}const d=a(o,[["render",p]]);export{y as __pageData,d as default};
